const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});try{const p=await browser.newPage();await p.setContent('<select id="model"></select>');
await p.evaluate(()=>{window.el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls;e.textContent=text;return e;};window.fetch=async()=>({ok:true,json:async()=>({codex:{default:'astra',models:[{id:'astra',label:'Astra'},{id:'other',label:'Other'}]},claude:{default:'fable',models:[{id:'fable',label:'Fable'},{id:'opus',label:'Opus'}]}})});});
const source=fs.readFileSync(path.join(__dirname,'../web/js/49-chat-workspace.js'),'utf8');await p.addScriptTag({content:source.slice(source.indexOf('let chatCodingCatalogPromise;'))});
await p.evaluate(()=>{chatPopulateModelSelect(document.querySelector('select'),'codex','');chatPopulateModelSelect(document.querySelector('select'),'claude','opus');});await p.waitForFunction(()=>document.querySelector('select').options.length===2);assert.equal(await p.locator('select').inputValue(),'opus');assert.deepEqual(await p.locator('option').evaluateAll(es=>es.map(e=>e.value)),['fable','opus']);
await p.evaluate(()=>chatPopulateModelSelect(document.querySelector('select'),'codex','custom-current'));await p.waitForFunction(()=>document.querySelector('select').options.length===3);assert.equal(await p.locator('select').inputValue(),'custom-current');
await p.evaluate(()=>chatPopulateModelSelect(document.querySelector('select'),'codex',''));await p.waitForFunction(()=>document.querySelector('select').options.length===2);assert.equal(await p.locator('select').inputValue(),'astra');console.log('PASS model picker: provider-switch race, exact current/custom model, configured default.');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
